hl.window_rule({
    name = "float-title",
    match = {
        title = "^(floating)$",
    },
    float = true,
})

hl.window_rule({
    name = "float-class",
    match = {
        class = "^(floating)$",
    },
    float = true,
    center = true,
    size = "70% 70%",
})

hl.window_rule({
    name = "suppress-maximize",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

hl.window_rule({
    name = "dropdown-term",
    match = {
        title = "^(dropdown-term)$",
    },
    float = true,
    size = "98% 60%",
    move = "1% 25",
    workspace = "special:term",
})

hl.window_rule({
    name = "foot-disposable",
    match = {
        title = "^(foot-disposable)$",
    },
    float = true,
})

hl.window_rule({
    name = "foot-tmux",
    match = {
        title = "^(foot-tmux)$",
    },
    float = true,
    workspace = "special:tmux",
})

hl.window_rule({
    name = "keepassxc",
    match = {
        class = "^(KeePassXC|keepassxc|org\\.keepassxc\\.KeePassXC)$",
    },
    workspace = "special:kp",
    center = true,
    size = "80% 80%",
})

hl.window_rule({
    name = "protonpass",
    match = {
        class = "^(proton-pass|Proton Pass)$",
    },
    workspace = "special:kp",
    center = true,
    size = "80% 80%",
})

hl.window_rule({
    name = "chatbot",
    match = {
        title = "^(chatbot)$",
    },
    workspace = "special:ai",
})

hl.window_rule({
    name = "note",
    match = {
        title = "^(note)$",
    },
    float = true,
    size = "60% 60%",
    center = true,
    workspace = "special:note",
})

