hl.on("hyprland.start", function()
    hl.exec_cmd("waybar & nm-applet & awww-daemon & dunst")
    hl.exec_cmd("tmux_manager.py --auto")
    hl.exec_cmd("systemd run --scope --user internxt webdav enable")
    hl.exec_cmd("ydotoold")
    hl.exec_cmd("dex -a")
end)

